CREATE OR REPLACE FUNCTION collect_ops.queue_receipt_exception_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if tg_table_name in('backlog_results','receipt_backlog_budget_deferrals')then
  if tg_table_name='receipt_backlog_budget_deferrals'then
   insert into collect_ops.receipt_backlog_sweep_sources(snapshot_id)values(new.snapshot_id)on conflict(snapshot_id)do nothing;
  elsif not new.business_handled then
   insert into collect_ops.receipt_backlog_sweep_sources(snapshot_id)values(new.snapshot_id)on conflict(snapshot_id)do nothing;
  end if;
  insert into collect_ops.receipt_exception_work(source_kind,source_id,origin)values('receipt_backlog',new.snapshot_id,'backlog');
 else
  insert into collect_ops.receipt_exception_work(source_kind,source_id,origin)values('receipt_event',new.event_id,
   case tg_table_name when 'event_deferrals'then 'deferral'else 'handled'end);
 end if;
 return new;end$function$

